export async function inspectVolume(name: string): Promise<VolumeOwnership | undefined> {
  const result = await runToCompletion("docker", ["volume", "inspect", name, "--format", "{{json .}}"], { timeoutMs: 30000 });
  if (result.exitCode !== 0) return undefined;
  const raw = JSON.parse(result.stdout.trim()) as { Name: string; Driver: string; Labels: Record<string, string> | null };
  const labels = raw.Labels ?? {};
  return {
    name: raw.Name,
    driver: raw.Driver,
    composeProject: labels["com.docker.compose.project"],
    composeVolumeKey: labels["com.docker.compose.volume"],
    labels,
  };
}

export async function volumeExists(name: string): Promise<boolean> {
  return (await inspectVolume(name)) !== undefined;
}

export interface ComposeBindMount {
  source: string;
  target: string;
  readOnly: boolean;
}

/** Host/port/database parsed out of a connection string — deliberately never the credentials or the raw value. */
export interface DatabaseTarget {
  host: string;
  port: string;
  database: string;
}

export interface ResolvedComposePersistence {
  /** Compose project name the resolved configuration will actually use. */
  projectName: string;
  /** Declared volume key in docker-compose.yml -> the real Docker volume name Compose will create. */
  volumeNames: Record<string, string>;
  /** Declared volume key -> `external: true`, which would make it a pre-existing user resource a test must never delete. */
  externalVolumes: string[];
  /** Service name -> its bind mounts (host source path, container target, read-only flag). */
  bindMounts: Record<string, ComposeBindMount[]>;
