import { fileURLToPath } from "node:url";
import { beforeAll, describe, expect, it } from "vitest";
import {
  isGitRepository,
  listIgnoredPaths,
  listTrackedFiles,
  listTrackedFilesMatchingIgnoreRules,
  listWorkingTreeEntries,
