3	/**
4	 * Minimal AWS Signature Version 4 signer for a single-object PUT/GET
5	 * against an S3-compatible endpoint (SeaweedFS's S3 gateway, configured
6	 * with docker/storage/s3-identities.json — see docker-compose.yml). This
7	 * implements only what the disposable smoke test needs: a single,
8	 * non-chunked PUT and a plain GET, path-style, no query-string signing,
9	 * no multipart upload.
10	 *
11	 * Built from the documented SigV4 algorithm (canonical request -> string
12	 * to sign -> derived signing key) using only Node's built-in `crypto`.
13	 * Originally written with no Docker available, and since **verified by
14	 * real execution** against the live `storage` container: a signed
15	 * createBucket + PUT + GET round-trip succeeds byte-for-byte (sub-issue
16	 * #47), and sub-issue #48's persistence check reuses the same signed
17	 * operations across container stop/start, recreation, and reset. The
18	 * header set and canonicalization below needed no adjustment.
19	 */
20	
21	export interface S3Credentials {
22	  accessKey: string;
23	  secretKey: string;
24	}
25	
26	export interface S3ObjectTarget {
27	  /** e.g. "http://localhost:8333" — the S3 gateway's own origin, no path. */
28	  endpoint: string;
29	  bucket: string;
30	  key: string;
31	  region?: string;
32	}
33	
34	function hmac(key: Buffer | string, data: string): Buffer {
35	  return createHmac("sha256", key).update(data, "utf8").digest();
36	}
37	
38	function sha256Hex(data: string | Buffer): string {
39	  return createHash("sha256").update(data).digest("hex");
40	}
41	
42	function amzDateStamp(date: Date): { amzDate: string; dateStamp: string } {
43	  const amzDate = date.toISOString().replace(/[:-]|\.\d{3}/g, "");
44	  return { amzDate, dateStamp: amzDate.slice(0, 8) };
45	}
46	
47	function deriveSigningKey(secretKey: string, dateStamp: string, region: string, service: string): Buffer {
48	  const kDate = hmac(`AWS4${secretKey}`, dateStamp);
49	  const kRegion = hmac(kDate, region);
50	  const kService = hmac(kRegion, service);
51	  return hmac(kService, "aws4_request");
52	}
53	
54	export interface SignedRequest {
55	  url: string;
56	  headers: Record<string, string>;
57	}
58	
59	export function signS3Request(
60	  method: "PUT" | "GET",
61	  target: S3ObjectTarget,
62	  credentials: S3Credentials,
63	  body: Buffer = Buffer.alloc(0),
64	  now: Date = new Date(),
65	): SignedRequest {
66	  const region = target.region ?? "us-east-1";
67	  const service = "s3";
68	  const endpointUrl = new URL(target.endpoint);
69	  const host = endpointUrl.host;
70	  // No trailing slash when `key` is empty (a bucket-level operation,
71	  // e.g. createBucket below) — `/bucket/` is a different resource than
72	  // `/bucket` for some S3-compatible servers.
73	  const canonicalUri = (target.key ? `/${target.bucket}/${target.key}` : `/${target.bucket}`).replace(/\/{2,}/g, "/");
74	  const payloadHash = sha256Hex(body);
75	  const { amzDate, dateStamp } = amzDateStamp(now);
76	
77	  const canonicalHeadersMap: Record<string, string> = {
78	    host,
79	    "x-amz-content-sha256": payloadHash,
80	    "x-amz-date": amzDate,
81	  };
82	  const signedHeaderNames = Object.keys(canonicalHeadersMap).sort();
83	  const canonicalHeaders = signedHeaderNames.map((name) => `${name}:${canonicalHeadersMap[name]}\n`).join("");
84	  const signedHeaders = signedHeaderNames.join(";");
85	
86	  const canonicalRequest = [method, canonicalUri, "", canonicalHeaders, signedHeaders, payloadHash].join("\n");
87	
88	  const credentialScope = `${dateStamp}/${region}/${service}/aws4_request`;
89	  const stringToSign = ["AWS4-HMAC-SHA256", amzDate, credentialScope, sha256Hex(canonicalRequest)].join("\n");
90	
91	  const signingKey = deriveSigningKey(credentials.secretKey, dateStamp, region, service);
92	  const signature = hmac(signingKey, stringToSign).toString("hex");
93	
94	  const authorization =
95	    `AWS4-HMAC-SHA256 Credential=${credentials.accessKey}/${credentialScope}, ` +
96	    `SignedHeaders=${signedHeaders}, Signature=${signature}`;
97	
98	  return {
99	    url: `${endpointUrl.origin}${canonicalUri}`,
100	    headers: {
101	      Host: host,
102	      "X-Amz-Date": amzDate,
103	      "X-Amz-Content-Sha256": payloadHash,
104	      Authorization: authorization,
105	    },
106	  };
107	}
108	
109	/**
110	 * `PUT /<bucket>` with no key and no body — the standard S3 bucket-creation
111	 * request. Verified necessary-or-not by direct inspection against a real
112	 * SeaweedFS instance: its S3 gateway auto-vivifies a bucket on the first
113	 * object PUT even without this call, but this is still issued
114	 * explicitly (disposable-bucket setup, not relying on that
115	 * server-specific convenience) so the round-trip does not depend on
116	 * auto-vivification behavior that is not part of the S3 API contract.
117	 */
118	export async function createBucket(target: Pick<S3ObjectTarget, "endpoint" | "bucket" | "region">, credentials: S3Credentials): Promise<Response> {
119	  const { url, headers } = signS3Request("PUT", { ...target, key: "" }, credentials);
120	  return fetch(url, { method: "PUT", headers });
121	}
122	
123	export async function putS3Object(target: S3ObjectTarget, credentials: S3Credentials, body: Buffer): Promise<Response> {
124	  const { url, headers } = signS3Request("PUT", target, credentials, body);
125	  return fetch(url, { method: "PUT", headers, body });
126	}
127	
128	export async function getS3Object(target: S3ObjectTarget, credentials: S3Credentials): Promise<Response> {
129	  const { url, headers } = signS3Request("GET", target, credentials);
130	  return fetch(url, { method: "GET", headers });
131	}

