 * gate itself, or either removal call throwing) is caught and reported
 * in that target's own outcome — it never stops or skips the other
 * targets, which is what makes this safe to use for partial setup
 * (e.g. a target whose containers never actually started).
 */
export async function cleanupDisposableTargets(targets: DisposableCleanupTarget[]): Promise<DisposableCleanupOutcome[]> {
  return Promise.all(
    targets.map(async (target): Promise<DisposableCleanupOutcome> => {
      try {
        const ownedVolumes = await target.listOwnedVolumes();
        if (ownedVolumes.length === 0) {
          // Nothing this target actually created — a safe no-op, not an ownership failure.
          await target.removeContainersKeepingVolumes();
          return { label: target.label, volumesDeleted: [], volumesRequiringManualInspection: [] };
        }

        const gate = await verifyAllVolumesOwnedForDeletion(ownedVolumes, target.ownershipContext);
        if (!gate.ok) {
          await target.removeContainersKeepingVolumes();
          return {
            label: target.label,
            volumesDeleted: [],
            volumesRequiringManualInspection: gate.checks
              .filter((check) => !check.ok)
              .map((check) => ({ name: check.name, reason: check.reason ?? "unknown" })),
          };
        }

        await target.removeContainersAndVolumes();
        return { label: target.label, volumesDeleted: ownedVolumes, volumesRequiringManualInspection: [] };
      } catch (error) {
        return { label: target.label, volumesDeleted: [], volumesRequiringManualInspection: [], error: String(error) };
      }
    }),
  );
}

