/**
 * Hard ownership gate, run immediately before the only destructive
 * command in this suite. Throws — stopping short of any deletion —
 * when ownership cannot be established for every named volume, rather
 * than deleting on an assumption.
 */
async function confirmDisposableOwnershipOrStop(names: string[]): Promise<void> {
  if (names.length === 0) {
    throw new Error("Refusing to reset: no volume was identified for this project, so ownership cannot be established.");
  }
  for (const name of names) {
    const ownership = await inspectVolume(name);
    if (!ownership) {
      throw new Error(`Refusing to reset: volume "${name}" could not be inspected, so its ownership cannot be established.`);
    }
    if (ownership.composeProject !== project.projectName) {
      throw new Error(
        `Refusing to reset: volume "${name}" is labelled com.docker.compose.project=` +
          `"${ownership.composeProject ?? "(none)"}", not this disposable test project "${project.projectName}". ` +
          `It may belong to a development stack or another user resource.`,
      );
    }
    if (baselineVolumeNames.includes(name)) {
      throw new Error(`Refusing to reset: volume "${name}" already existed before this test ran — it is a pre-existing resource.`);
    }
  }
}

