afterAll(async () => {
  // Both projects are torn down even when a test above failed, and a
  // cleanup failure for EITHER is reported rather than swallowed.
  // Vitest records a hook failure as its own, additional failure — it
  // never replaces or hides an earlier test's failure, so the original
  // cause always stays visible. Each call is scoped to exactly one
  // project (`composeDown`'s own guarantee).
  const cleanupFailures: string[] = [];
  for (const target of [project, bystander]) {
    try {
      await cleanupComposeProject(target, { timeoutMs: 180000 });
    } catch (error) {
      cleanupFailures.push(`cleanup of "${target.projectName}" failed: ${String(error)}`);
    }
  }

  // Verify the cleanup's RESULT rather than trusting its exit code.
  const survivors = new Set(await listAllVolumeNames());
  for (const target of [project, bystander]) {
    const remaining = await listVolumeNamesByComposeProject(target);
    if (remaining.length > 0) {
      cleanupFailures.push(`volumes still labelled for project "${target.projectName}": ${remaining.join(", ")}`);
    }
  }
  const destroyedBystanders = baselineVolumeNames.filter((name) => !survivors.has(name));
  if (destroyedBystanders.length > 0) {
    cleanupFailures.push(`pre-existing volumes no longer present (MUST NOT happen): ${destroyedBystanders.join(", ")}`);
  }

  if (cleanupFailures.length > 0) {
    throw new Error(`Cleanup did not complete correctly:\n- ${cleanupFailures.join("\n- ")}`);
  }
}, 420000);

