export interface DisposableCleanupTarget {
  /** Identifies this target in a reported outcome — typically the Compose project name. */
  label: string;
  /** The volume names the DAEMON currently reports as owned by this target (e.g. `listVolumeNamesByComposeProject`). May resolve to `[]` if nothing was ever created — a safe no-op, not an ownership failure. */
  listOwnedVolumes: () => Promise<string[]>;
  /** Context used to verify EVERY one of those volume names immediately before they are destroyed. */
  ownershipContext: VolumeOwnershipContext;
  /** Removes this target's containers/network but KEEPS its volumes. Always safe to call: it never touches another target's resources, and never deletes data. */
  removeContainersKeepingVolumes: () => Promise<void>;
  /** Removes this target's containers/network AND its named volumes. Only ever invoked by `cleanupDisposableTargets` after every one of its volumes has passed the ownership gate. */
  removeContainersAndVolumes: () => Promise<void>;
}

export interface DisposableCleanupOutcome {
  label: string;
  volumesDeleted: string[];
  volumesRequiringManualInspection: { name: string; reason: string }[];
  /** Set when something about processing this target itself failed (listing its volumes, or either removal call). */
  error?: string;
}

/**
 * Cleans up multiple disposable targets independently and safely.
 *
 * For EACH target: lists the volumes the daemon currently reports it
 * owns, then re-verifies ownership of every one of them (via
 * `verifyAllVolumesOwnedForDeletion`) immediately before any destructive
 * step — never relying on an ownership check performed earlier in the
 * test run, since the exact resources present at cleanup time are what
 * matters. Only when EVERY volume passes is `removeContainersAndVolumes`
 * invoked; otherwise this REFUSES the destructive step for that target
 * entirely (removing only containers/network, which is always safe
 * since they belong solely to that target's own Compose project) and
 * reports exactly which volumes require manual inspection, with why.
 *
 * A failure processing ONE target (listing its volumes, the ownership
 * gate itself, or either removal call throwing) is caught and reported
 * in that target's own outcome — it never stops or skips the other
 * targets, which is what makes this safe to use for partial setup
 * (e.g. a target whose containers never actually started).
 */
export async function cleanupDisposableTargets(targets: DisposableCleanupTarget[]): Promise<DisposableCleanupOutcome[]> {
  return Promise.all(
    targets.map(async (target): Promise<DisposableCleanupOutcome> => {
      try {
        const ownedVolumes = await target.listOwnedVolumes();
        if (ownedVolumes.length === 0) {
          // Nothing this target actually created — a safe no-op, not an ownership failure.
          await target.removeContainersKeepingVolumes();
          return { label: target.label, volumesDeleted: [], volumesRequiringManualInspection: [] };
        }

        const gate = await verifyAllVolumesOwnedForDeletion(ownedVolumes, target.ownershipContext);
        if (!gate.ok) {
          await target.removeContainersKeepingVolumes();
