        const owned = await target.listOwnedVolumesWithOwnership();
        if (owned.length === 0) {
          // Nothing this target actually created — a safe no-op, not an ownership failure.
          await target.removeContainersKeepingVolumes();
          return { label: target.label, volumesDeleted: [], volumesRequiringManualInspection: [] };
        }

        const checks = owned.map((record) => checkVolumeOwnershipForDeletion(record.name, record.ownership, target.ownershipContext));
        if (!checks.every((check) => check.ok)) {
          await target.removeContainersKeepingVolumes();
          return {
            label: target.label,
            volumesDeleted: [],
            volumesRequiringManualInspection: checks
              .filter((check) => !check.ok)
              .map((check) => ({ name: check.name, reason: check.reason ?? "unknown" })),
          };
        }

        await target.removeContainersAndVolumes();
        return { label: target.label, volumesDeleted: owned.map((record) => record.name), volumesRequiringManualInspection: [] };
      } catch (error) {
        return { label: target.label, volumesDeleted: [], volumesRequiringManualInspection: [], error: String(error) };
      }
    }),
  );
}

/**
 * The real-Docker implementation of `DisposableCleanupTarget.listOwnedVolumesWithOwnership`:
 * lists the volumes the daemon reports as owned by `project`, then
 * inspects EACH ONE for its real ownership. An inspection FAILURE (not
 * merely absence — see `inspectVolume`) is NOT swallowed here: it
 * propagates, so `cleanupDisposableTargets` reports it as that target's
 * own `error` rather than quietly treating a daemon problem as an
 * ownership mismatch.
 */
export async function listOwnedVolumesWithOwnership(project: ComposeProject): Promise<OwnedVolumeRecord[]> {
  const names = await listVolumeNamesByComposeProject(project);
  return Promise.all(names.map(async (name) => ({ name, ownership: await inspectVolume(name) })));
}

