export interface VolumeDeletionCheck {
  name: string;
  ok: boolean;
  /** Present when `ok` is false — the exact reason deletion was refused, for a "requires manual inspection" report. */
  reason?: string;
}

export interface VolumeOwnershipContext {
  /** The Compose project this volume is expected to be labelled with. */
  expectedProjectName: string;
  /** Volume names that already existed on the daemon before this run started — see `listAllVolumeNames`. */
  baselineVolumeNames: readonly string[];
  /** Volume KEYS (docker-compose.yml's own `volumes:` keys, e.g. "postgres-data") declared `external: true` — a pre-existing user resource, never one this stack created. */
  externalVolumeKeys: readonly string[];
}

/**
 * Pure ownership gate for ONE volume, given already-fetched facts: it
 * never queries the daemon itself, which is what makes it independently
 * unit-testable with constructed fakes (no real Docker, no risk to any
 * real volume). Safe to delete requires ALL of:
 *   - `ownership` was actually established (not `undefined` — an
 *     inspection failure or genuine absence must never read as "safe").
 *   - The volume is NOT in `context.baselineVolumeNames` — it did not
 *     already exist before this run.
 *   - Its `com.docker.compose.project` label matches
 *     `context.expectedProjectName` exactly — it belongs to THIS
 *     disposable project, not a development stack or another project.
 *   - Its `com.docker.compose.volume` key is not one of
 *     `context.externalVolumeKeys` — it was not declared `external:
 *     true` (which would make it a pre-existing resource regardless of
 *     its labels).
 */
export function checkVolumeOwnershipForDeletion(
  name: string,
  ownership: VolumeOwnership | undefined,
  context: VolumeOwnershipContext,
): VolumeDeletionCheck {
  if (!ownership) {
    return { name, ok: false, reason: "could not be inspected (absent or inspection failed) — ownership cannot be established" };
  }
  if (context.baselineVolumeNames.includes(name)) {
    return { name, ok: false, reason: "already existed on the daemon before this run started — it is a pre-existing resource" };
  }
  if (ownership.composeProject !== context.expectedProjectName) {
    return {
      name,
      ok: false,
      reason:
        `labelled com.docker.compose.project="${ownership.composeProject ?? "(none)"}", not the expected disposable ` +
        `project "${context.expectedProjectName}" — it may belong to a development stack or another user resource`,
    };
  }
  if (ownership.composeVolumeKey !== undefined && context.externalVolumeKeys.includes(ownership.composeVolumeKey)) {
    return {
      name,
      ok: false,
      reason: `implements volume key "${ownership.composeVolumeKey}", declared external:true — a pre-existing user resource`,
    };
  }
  return { name, ok: true };
}

/**
 * `checkVolumeOwnershipForDeletion`, but fetches `ownership` itself via
 * `inspectVolume` — an inspection FAILURE (not merely absence) is caught
 * here and reported as a non-ok check with the real error message,
 * rather than propagating and aborting whatever batch this is part of.
 * This is what lets a caller processing several volumes (or several
 * disposable projects) keep going and report every problem, instead of
 * one inspection error stopping the whole gate.
 */
export async function verifyVolumeOwnershipForDeletion(name: string, context: VolumeOwnershipContext): Promise<VolumeDeletionCheck> {
  let ownership: VolumeOwnership | undefined;
  try {
    ownership = await inspectVolume(name);
  } catch (error) {
    return { name, ok: false, reason: `could not be inspected: ${String(error)}` };
  }
  return checkVolumeOwnershipForDeletion(name, ownership, context);
}

export interface OwnershipGateResult {
  ok: boolean;
  checks: VolumeDeletionCheck[];
}

/**
 * The hard gate a destructive reset or cleanup must pass before
 * `--volumes` is ever issued: every one of `names` must independently
 * pass `verifyVolumeOwnershipForDeletion`. An empty `names` list is
 * itself refused (there is nothing to establish ownership of, which
 * must never be read as "nothing to check, proceed").
 */
export async function verifyAllVolumesOwnedForDeletion(names: readonly string[], context: VolumeOwnershipContext): Promise<OwnershipGateResult> {
  if (names.length === 0) {
    return {
      ok: false,
      checks: [{ name: "(none)", ok: false, reason: "no volume was identified for this project — ownership cannot be established" }],
    };
  }
  const checks = await Promise.all(names.map((name) => verifyVolumeOwnershipForDeletion(name, context)));
  return { ok: checks.every((check) => check.ok), checks };
}

export interface ProvisioningSafetyCheck {
  ok: boolean;
  problems: string[];
}

/**
 * Validates a RESOLVED Compose configuration is safe to provision as a
 * disposable project — called BEFORE any container or volume is
 * created, using only the static `docker compose config` output (no
 * daemon query, which is what makes this pure and unit-testable with a
 * constructed `ResolvedComposePersistence`). Every declared volume must:
 *   - Resolve to a name actually prefixed by the project's own name
 *     (`<project>_<key>` or `<project>-<key>`), so it cannot collide
 *     with a different project's volume.
 *   - Not be declared `external: true` — that would point at a
 *     pre-existing user resource this stack must never create or
 *     destroy.
 *   - Not already exist on the daemon (the pre-captured baseline) —
 *     catches the one scenario volume-name-prefixing alone cannot: a
 *     volume that, by coincidence or a reused project name, already
 *     exists under the exact name this run is about to use.
 */
export function checkProvisioningSafety(
  resolved: ResolvedComposePersistence,
  baselineVolumeNames: readonly string[],
): ProvisioningSafetyCheck {
  const problems: string[] = [];
  if (resolved.externalVolumes.length > 0) {
    problems.push(`volume key(s) declared external:true: ${resolved.externalVolumes.join(", ")} — refusing a pre-existing resource`);
  }
  for (const [key, name] of Object.entries(resolved.volumeNames)) {
    if (!name.startsWith(`${resolved.projectName}_`) && !name.startsWith(`${resolved.projectName}-`)) {
      problems.push(`volume "${name}" (key "${key}") is not scoped to project "${resolved.projectName}" by name`);
    }
    if (baselineVolumeNames.includes(name)) {
      problems.push(`volume "${name}" (key "${key}") already exists on the daemon before this run started`);
    }
  }
  return { ok: problems.length === 0, problems };
}

/** `checkProvisioningSafety`, but throws — stopping short of provisioning anything — when the check fails. */
export function assertProvisioningSafety(resolved: ResolvedComposePersistence, baselineVolumeNames: readonly string[]): void {
  const check = checkProvisioningSafety(resolved, baselineVolumeNames);
  if (!check.ok) {
    throw new Error(`Refusing to provision disposable project "${resolved.projectName}":\n- ${check.problems.join("\n- ")}`);
  }
}

/** `composeDownKeepVolumes`, but throws on a nonzero exit instead of returning a result the caller might forget to check. */
export async function removeContainersKeepingVolumesOrThrow(project: ComposeProject, options: { timeoutMs?: number } = {}): Promise<void> {
  const result = await composeDownKeepVolumes(project, options);
  if (result.exitCode !== 0) {
    throw new Error(
      `docker compose down (keeping volumes) failed for project "${project.projectName}" (exit ${result.exitCode}):\n` +
        `stdout:\n${result.stdout}\nstderr:\n${result.stderr}`,
    );
  }
}

/** One volume the daemon reports as owned by a target, paired with its freshly-fetched ownership (or `undefined` for a genuinely-absent or failed inspection). */
export interface OwnedVolumeRecord {
  name: string;
  ownership: VolumeOwnership | undefined;
}

export interface DisposableCleanupTarget {
  /** Identifies this target in a reported outcome — typically the Compose project name. */
  label: string;
  /**
   * The volumes the DAEMON currently reports as owned by this target,
   * EACH ALREADY PAIRED with its own freshly-fetched ownership (see
   * `listOwnedVolumesWithOwnership` for the real-Docker implementation).
   * Resolving ownership here, rather than inside `cleanupDisposableTargets`
   * itself, is what keeps this function's own decision logic pure and
   * independently unit-testable with constructed fakes — no real Docker
   * call is hard-wired into it. May resolve to `[]` if nothing was ever
   * created for this target — a safe no-op, not an ownership failure.
   */
  listOwnedVolumesWithOwnership: () => Promise<OwnedVolumeRecord[]>;
  /** Context used to verify EVERY one of those volumes immediately before they are destroyed. */
  ownershipContext: VolumeOwnershipContext;
  /** Removes this target's containers/network but KEEPS its volumes. Always safe to call: it never touches another target's resources, and never deletes data. */
  removeContainersKeepingVolumes: () => Promise<void>;
  /** Removes this target's containers/network AND its named volumes. Only ever invoked by `cleanupDisposableTargets` after every one of its volumes has passed the ownership gate. */
  removeContainersAndVolumes: () => Promise<void>;
}

export interface DisposableCleanupOutcome {
  label: string;
  volumesDeleted: string[];
  volumesRequiringManualInspection: { name: string; reason: string }[];
  /** Set when something about processing this target itself failed (listing/inspecting its volumes, or either removal call). */
  error?: string;
}

/**
 * Cleans up multiple disposable targets independently and safely.
 *
 * For EACH target: fetches its owned volumes together with their
 * ownership (`listOwnedVolumesWithOwnership`), then re-checks EVERY one
 * of them with the PURE `checkVolumeOwnershipForDeletion` immediately
 * before any destructive step — never relying on an ownership check
 * performed earlier in the test run, since the exact resources present
 * at cleanup time are what matters. Only when EVERY volume passes is
 * `removeContainersAndVolumes` invoked; otherwise this REFUSES the
 * destructive step for that target entirely (removing only
 * containers/network, which is always safe since they belong solely to
 * that target's own Compose project) and reports exactly which volumes
 * require manual inspection, with why.
 *
 * A failure processing ONE target (fetching its volumes/ownership, or
 * either removal call throwing) is caught and reported in that target's
 * own outcome — it never stops or skips the other targets, which is
 * what makes this safe to use for partial setup (e.g. a target whose
 * containers never actually started).
 */
export async function cleanupDisposableTargets(targets: DisposableCleanupTarget[]): Promise<DisposableCleanupOutcome[]> {
  return Promise.all(
    targets.map(async (target): Promise<DisposableCleanupOutcome> => {
      try {
        const owned = await target.listOwnedVolumesWithOwnership();
        if (owned.length === 0) {
          // Nothing this target actually created — a safe no-op, not an ownership failure.
          await target.removeContainersKeepingVolumes();
          return { label: target.label, volumesDeleted: [], volumesRequiringManualInspection: [] };
        }

        const checks = owned.map((record) => checkVolumeOwnershipForDeletion(record.name, record.ownership, target.ownershipContext));
        if (!checks.every((check) => check.ok)) {
          await target.removeContainersKeepingVolumes();
          return {
            label: target.label,
            volumesDeleted: [],
            volumesRequiringManualInspection: checks
              .filter((check) => !check.ok)
              .map((check) => ({ name: check.name, reason: check.reason ?? "unknown" })),
          };
        }

        await target.removeContainersAndVolumes();
        return { label: target.label, volumesDeleted: owned.map((record) => record.name), volumesRequiringManualInspection: [] };
      } catch (error) {
        return { label: target.label, volumesDeleted: [], volumesRequiringManualInspection: [], error: String(error) };
      }
    }),
  );
}

/**
 * The real-Docker implementation of `DisposableCleanupTarget.listOwnedVolumesWithOwnership`:
 * lists the volumes the daemon reports as owned by `project`, then
 * inspects EACH ONE for its real ownership. An inspection FAILURE (not
 * merely absence — see `inspectVolume`) is NOT swallowed here: it
 * propagates, so `cleanupDisposableTargets` reports it as that target's
 * own `error` rather than quietly treating a daemon problem as an
 * ownership mismatch.
 */
export async function listOwnedVolumesWithOwnership(project: ComposeProject): Promise<OwnedVolumeRecord[]> {
  const names = await listVolumeNamesByComposeProject(project);
  return Promise.all(names.map(async (name) => ({ name, ownership: await inspectVolume(name) })));
}

