 52	function fakeVolumeOwnership(overrides: Partial<VolumeOwnership> = {}): VolumeOwnership {
 53	  return {
 54	    name: "relis-persist-aaaa1111_postgres-data",
 55	    driver: "local",
 56	    composeProject: "relis-persist-aaaa1111",
 57	    composeVolumeKey: "postgres-data",
 58	    labels: {},
 59	    ...overrides,
 60	  };
 61	}
