 63	function fakeResolvedPersistence(overrides: Partial<ResolvedComposePersistence> = {}): ResolvedComposePersistence {
 64	  return {
 65	    projectName: "relis-persist-aaaa1111",
 66	    volumeNames: {
 67	      "postgres-data": "relis-persist-aaaa1111_postgres-data",
 68	      "storage-data": "relis-persist-aaaa1111_storage-data",
 69	    },
 70	    externalVolumes: [],
 71	    bindMounts: {},
 72	    databaseTargets: {},
 73	    ...overrides,
 74	  };
 75	}
