 92	  it("does NOT match a daemon-unreachable error", () => {
 93	    expect(
 94	      isVolumeNotFoundError('error during connect: Get "http://127.0.0.1:1/v1.56/volumes/x": dial tcp 127.0.0.1:1: connectex: connection refused'),
 95	    ).toBe(false);
 96	  });
 97	
 98	  it("does NOT match a permission failure", () => {
 99	    expect(isVolumeNotFoundError("permission denied while trying to connect to the Docker daemon socket")).toBe(false);
100	  });
101	
102	  it("does NOT match an empty or unrelated message", () => {
103	    expect(isVolumeNotFoundError("")).toBe(false);
104	    expect(isVolumeNotFoundError("Error response from daemon: something else entirely")).toBe(false);
105	  });
