108	// The one real-Docker check in this file. Inspecting a volume name that
109	// is guaranteed never to exist is read-only and risk-free: it creates
110	// nothing and can destroy nothing. Gated and skipped (not mocked) when
111	// Docker is unavailable, matching every other real-Docker suite here.
112	const dockerAvailable = isDockerAvailableSync();
113	if (!dockerAvailable) {
114	  // eslint-disable-next-line no-console
115	  console.warn(
116	    "[docker-compose/persistence-safety.test.ts] One block SKIPPED: the `docker` CLI is not available (or no daemon " +
117	      "is reachable). The genuine-absence check against a real daemon was not verified; every other check in this " +
118	      "file uses controlled fakes and still ran.",
119	  );
