122	describe.runIf(dockerAvailable)("inspectVolume/volumeExists — genuine absence, verified against the real daemon", () => {
123	  it("resolves to undefined/false for a volume name guaranteed not to exist, never throwing", async () => {
124	    const neverExists = uniqueProjectName("relis-persistence-safety-never-exists");
125	    await expect(inspectVolume(neverExists)).resolves.toBeUndefined();
126	    await expect(volumeExists(neverExists)).resolves.toBe(false);
127	  });
128	});
