130	describe("checkVolumeOwnershipForDeletion — ownership rejection with controlled fakes", () => {
131	  it("accepts a volume that genuinely belongs to the expected project and nothing else", () => {
132	    const result = checkVolumeOwnershipForDeletion("relis-persist-aaaa1111_postgres-data", fakeVolumeOwnership(), BASE_CONTEXT);
133	    expect(result).toEqual({ name: "relis-persist-aaaa1111_postgres-data", ok: true });
134	  });
135	
136	  it("refuses when ownership could not be established at all (undefined)", () => {
137	    const result = checkVolumeOwnershipForDeletion("some-volume", undefined, BASE_CONTEXT);
138	    expect(result.ok).toBe(false);
139	    expect(result.reason).toMatch(/could not be inspected/i);
140	  });
141	
142	  it("refuses a volume that already existed before this run (the baseline)", () => {
143	    const name = "relis-persist-aaaa1111_postgres-data";
144	    const result = checkVolumeOwnershipForDeletion(name, fakeVolumeOwnership(), { ...BASE_CONTEXT, baselineVolumeNames: [name] });
145	    expect(result.ok).toBe(false);
