147	  });
148	
149	  it("refuses a volume labelled with a DIFFERENT Compose project — never a name-prefix guess", () => {
150	    const result = checkVolumeOwnershipForDeletion(
151	      "relis-persist-aaaa1111_postgres-data",
152	      fakeVolumeOwnership({ composeProject: "someone-elses-dev-stack" }),
