157	    expect(result.reason).toContain(BASE_CONTEXT.expectedProjectName);
158	  });
159	
160	  it("refuses a volume with no Compose project label at all", () => {
161	    const result = checkVolumeOwnershipForDeletion(
162	      "relis-persist-aaaa1111_postgres-data",
163	      fakeVolumeOwnership({ composeProject: undefined }),
164	      BASE_CONTEXT,
165	    );
166	    expect(result.ok).toBe(false);
167	    expect(result.reason).toContain("(none)");
168	  });
169	
170	  it("refuses a volume whose key is declared external:true, even if its project label matches", () => {
171	    const result = checkVolumeOwnershipForDeletion("relis-persist-aaaa1111_postgres-data", fakeVolumeOwnership(), {
172	      ...BASE_CONTEXT,
