180	describe("verifyAllVolumesOwnedForDeletion — the batch gate used immediately before every destructive step", () => {
181	  it("refuses an empty volume list rather than treating 'nothing to check' as 'safe to proceed'", async () => {
182	    const gate = await verifyAllVolumesOwnedForDeletion([], BASE_CONTEXT);
