236	describe("cleanupDisposableTargets — partial setup and per-target ownership refusal, with fakes", () => {
237	  /**
238	   * Builds a fake target with call-tracking, never touching any real
239	   * process or Docker daemon: `owned` supplies already-paired
240	   * name/ownership records directly (or a function, to simulate a
241	   * listing failure), exactly mirroring what the real
242	   * `listOwnedVolumesWithOwnership` would return — WITHOUT this
243	   * function ever calling the real one.
244	   */
245	  function fakeTarget(options: {
246	    label: string;
247	    owned: OwnedVolumeRecord[] | (() => Promise<OwnedVolumeRecord[]>);
248	    context?: VolumeOwnershipContext;
249	  }): DisposableCleanupTarget & { keepCalls: number; destroyCalls: number } {
250	    const calls = { keep: 0, destroy: 0 };
251	    const fixedOwned = options.owned;
252	    const listOwnedVolumesWithOwnership: () => Promise<OwnedVolumeRecord[]> =
253	      typeof fixedOwned === "function" ? fixedOwned : async () => fixedOwned;
254	    const target: DisposableCleanupTarget & { keepCalls: number; destroyCalls: number } = {
255	      label: options.label,
256	      listOwnedVolumesWithOwnership,
257	      ownershipContext: options.context ?? { ...BASE_CONTEXT, expectedProjectName: options.label },
258	      removeContainersKeepingVolumes: async () => {
259	        calls.keep += 1;
260	      },
261	      removeContainersAndVolumes: async () => {
262	        calls.destroy += 1;
263	      },
264	      get keepCalls() {
265	        return calls.keep;
266	      },
267	      get destroyCalls() {
268	        return calls.destroy;
269	      },
270	    };
271	    return target;
272	  }
273	
274	  it("treats a target with no owned volumes as a safe no-op — never a destructive call", async () => {
275	    const target = fakeTarget({ label: "relis-empty-target", owned: [] });
276	    const [outcome] = await cleanupDisposableTargets([target]);
277	    expect(outcome).toEqual({ label: "relis-empty-target", volumesDeleted: [], volumesRequiringManualInspection: [] });
278	    expect(target.keepCalls).toBe(1);
279	    expect(target.destroyCalls).toBe(0);
280	  });
281	
282	  it("destroys volumes only once EVERY one of them passes the ownership gate", async () => {
283	    const ownedVolumeName = "relis-good-target_postgres-data";
284	    const context: VolumeOwnershipContext = { expectedProjectName: "relis-good-target", baselineVolumeNames: [], externalVolumeKeys: [] };
285	    const target = fakeTarget({
286	      label: "relis-good-target",
287	      owned: [{ name: ownedVolumeName, ownership: fakeVolumeOwnership({ name: ownedVolumeName, composeProject: "relis-good-target" }) }],
288	      context,
289	    });
290	    const [outcome] = await cleanupDisposableTargets([target]);
291	    expect(outcome).toEqual({ label: "relis-good-target", volumesDeleted: [ownedVolumeName], volumesRequiringManualInspection: [] });
292	    expect(target.destroyCalls).toBe(1);
293	    expect(target.keepCalls).toBe(0);
294	  });
295	
296	  it("REFUSES deletion and reports the exact volume requiring manual inspection when ownership fails", async () => {
297	    const preExistingName = "relis-risky-target_postgres-data";
298	    const target = fakeTarget({
299	      label: "relis-risky-target",
300	      // Ownership itself looks fine (correct project label) — it is the
301	      // BASELINE (pre-existing before this run) that must refuse it.
302	      owned: [{ name: preExistingName, ownership: fakeVolumeOwnership({ name: preExistingName, composeProject: "relis-risky-target" }) }],
303	      context: { expectedProjectName: "relis-risky-target", baselineVolumeNames: [preExistingName], externalVolumeKeys: [] },
304	    });
305	    const [outcome] = await cleanupDisposableTargets([target]);
306	    expect(outcome.volumesDeleted).toEqual([]);
307	    expect(outcome.volumesRequiringManualInspection).toEqual([{ name: preExistingName, reason: expect.stringMatching(/pre-existing/i) }]);
308	    // The destructive call must never have been made; only the safe,
309	    // containers-only removal runs.
310	    expect(target.destroyCalls).toBe(0);
311	    expect(target.keepCalls).toBe(1);
312	  });
313	
314	  it("REFUSES deletion when a volume's ownership could not be established at all (undefined — absent or inspection failed)", async () => {
315	    const name = "relis-uninspectable-target_postgres-data";
316	    const target = fakeTarget({
317	      label: "relis-uninspectable-target",
318	      owned: [{ name, ownership: undefined }],
319	    });
320	    const [outcome] = await cleanupDisposableTargets([target]);
321	    expect(outcome.volumesDeleted).toEqual([]);
322	    expect(outcome.volumesRequiringManualInspection).toEqual([{ name, reason: expect.stringMatching(/could not be inspected/i) }]);
323	    expect(target.destroyCalls).toBe(0);
324	    expect(target.keepCalls).toBe(1);
325	  });
326	
327	  it("handles a target whose setup never actually started (listing its volumes throws) without crashing or faking success", async () => {
328	    const target: DisposableCleanupTarget = {
329	      label: "relis-never-started",
330	      listOwnedVolumesWithOwnership: async () => {
331	        throw new Error("docker compose ps failed: no such project");
332	      },
333	      ownershipContext: { ...BASE_CONTEXT, expectedProjectName: "relis-never-started" },
334	      removeContainersKeepingVolumes: async () => {
335	        throw new Error("should never be called");
336	      },
337	      removeContainersAndVolumes: async () => {
338	        throw new Error("should never be called");
339	      },
340	    };
341	    const [outcome] = await cleanupDisposableTargets([target]);
342	    expect(outcome.error).toMatch(/no such project/i);
343	    expect(outcome.volumesDeleted).toEqual([]);
344	    expect(outcome.volumesRequiringManualInspection).toEqual([]);
345	  });
346	
347	  it("processes multiple targets INDEPENDENTLY — one target's failure never stops or skips another's cleanup", async () => {
348	    const neverStarted: DisposableCleanupTarget = {
349	      label: "relis-partial-a",
350	      listOwnedVolumesWithOwnership: async () => {
351	        throw new Error("never actually started");
352	      },
353	      ownershipContext: { ...BASE_CONTEXT, expectedProjectName: "relis-partial-a" },
354	      removeContainersKeepingVolumes: async () => undefined,
355	      removeContainersAndVolumes: async () => undefined,
356	    };
357	    const riskyName = "relis-partial-b_postgres-data";
358	    const riskyOne = fakeTarget({
359	      label: "relis-partial-b",
360	      owned: [{ name: riskyName, ownership: fakeVolumeOwnership({ name: riskyName, composeProject: "relis-partial-b" }) }],
361	      context: { expectedProjectName: "relis-partial-b", baselineVolumeNames: [riskyName], externalVolumeKeys: [] },
362	    });
363	    const healthyName = "relis-partial-c_postgres-data";
364	    const healthyOne = fakeTarget({
365	      label: "relis-partial-c",
366	      owned: [{ name: healthyName, ownership: fakeVolumeOwnership({ name: healthyName, composeProject: "relis-partial-c" }) }],
367	      context: { expectedProjectName: "relis-partial-c", baselineVolumeNames: [], externalVolumeKeys: [] },
368	    });
369	
370	    const outcomes = await cleanupDisposableTargets([neverStarted, riskyOne, healthyOne]);
371	
372	    expect(outcomes).toHaveLength(3);
373	    const byLabel = Object.fromEntries(outcomes.map((outcome) => [outcome.label, outcome]));
374	
375	    expect(byLabel["relis-partial-a"]?.error).toMatch(/never actually started/i);
376	    expect(byLabel["relis-partial-b"]?.volumesRequiringManualInspection).toHaveLength(1);
377	    expect(byLabel["relis-partial-b"]?.volumesDeleted).toEqual([]);
378	    expect(byLabel["relis-partial-c"]?.volumesDeleted).toEqual([healthyName]);
379	
380	    // The healthy target's own destructive call ran, and the risky
381	    // target's never did — proving the failure/refusal for the other two
382	    // targets did not suppress or alter this target's own outcome.
383	    expect(healthyOne.destroyCalls).toBe(1);
384	    expect(riskyOne.destroyCalls).toBe(0);
385	  });
386	});
