388	describe("parseS3ErrorBody / isS3ObjectAbsent — a specific S3 'not found', never merely 'any error'", () => {
389	  const NO_SUCH_KEY_BODY =
390	    '<?xml version="1.0" encoding="UTF-8"?>\n<Error><Code>NoSuchKey</Code><Message>The specified key does not exist.</Message></Error>';
391	  const NO_SUCH_BUCKET_BODY =
392	    '<?xml version="1.0" encoding="UTF-8"?>\n<Error><Code>NoSuchBucket</Code><Message>The specified bucket does not exist.</Message></Error>';
393	  const ACCESS_DENIED_BODY = '<?xml version="1.0" encoding="UTF-8"?>\n<Error><Code>AccessDenied</Code><Message>Access Denied.</Message></Error>';
394	
395	  it("parses a real NoSuchKey body", () => {
396	    expect(parseS3ErrorBody(NO_SUCH_KEY_BODY)).toEqual({ code: "NoSuchKey", message: "The specified key does not exist." });
397	  });
398	
399	  it("parses a real NoSuchBucket body", () => {
400	    expect(parseS3ErrorBody(NO_SUCH_BUCKET_BODY)).toEqual({ code: "NoSuchBucket", message: "The specified bucket does not exist." });
401	  });
402	
403	  it("returns undefined fields for a body that isn't a recognizable S3 XML error (never throws)", () => {
