405	    expect(parseS3ErrorBody("<html><body>502 Bad Gateway</body></html>")).toEqual({ code: undefined, message: undefined });
406	  });
407	
408	  it("accepts ONLY HTTP 404 with NoSuchKey or NoSuchBucket as absence", () => {
