46	/**
47	 * Finds a currently-free TCP port on loopback by briefly binding to port
48	 * 0 and reading back the OS-assigned port, then releasing it
49	 * immediately.
50	 *
51	 * This exists specifically for NGINX_HTTP_PORT, and must NOT be confused
52	 * with the "pass 0, discover the real port with `composePort` afterward"
53	 * pattern used for MAILHOG_UI_PORT/SEAWEEDFS_S3_PORT: those two variables
54	 * are never read by any application code, so discovering the real port
55	 * AFTER `docker compose up` is fine. NGINX_HTTP_PORT is different — it is
56	 * baked directly into `NEXT_PUBLIC_API_URL` on the `web` service at
57	 * container start (see docker-compose.yml). Passing the literal string
58	 * "0" there bakes the broken value "http://localhost:0/api" into the
59	 * running container; the real port must be known BEFORE `docker compose
60	 * up` runs, which is what this function is for.
61	 *
62	 * Has the usual small TOCTOU race (another process could claim the port
63	 * between this closing it and Compose binding it) — an accepted
64	 * trade-off for a disposable local test run, same as any "find a free
65	 * port" test helper.
66	 */
67	export async function getFreePort(): Promise<number> {
68	  return new Promise((resolve, reject) => {
69	    const server = createServer();
70	    server.unref();
71	    server.on("error", reject);
72	    server.listen(0, "127.0.0.1", () => {
73	      const address = server.address();
74	      if (address === null || typeof address === "string") {
75	        server.close();
76	        reject(new Error("Could not determine an assigned port"));
77	        return;
78	      }
79	      const { port } = address;
80	      server.close(() => resolve(port));
81	    });
82	  });
83	}
